function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 30) return 'grid needs 1 to 30 rows.';
  const n = grid.length;
  if (grid.some(row => typeof row !== 'string' || row.length !== n)) return 'grid must be square: every row has n characters.';
  if (grid.some(row => /[^/\\ ]/.test(row))) return "Each square is '/', '\\' or ' '.";
  return null;
}

