function regionsBySlashes(grid) {
  const n = grid.length;
  const TOP = 0;
  const RIGHT = 1;
  const BOTTOM = 2;
  const LEFT = 3;
  const parent = Array.from({ length: 4 * n * n }, (_, index) => index);
  let regions = 4 * n * n;

  function find(x) {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }

  function union(a, b) {
    const rootA = find(a);
    const rootB = find(b);
    if (rootA !== rootB) {
      parent[rootA] = rootB;
      regions--;
    }
  }

  for (let row = 0; row < n; row++) {
    for (let col = 0; col < n; col++) {
      const base = 4 * (row * n + col);
      const cell = grid[row][col];
      if (cell !== "\\") {
        union(base + TOP, base + LEFT);
        union(base + RIGHT, base + BOTTOM);
      }
      if (cell !== "/") {
        union(base + TOP, base + RIGHT);
        union(base + BOTTOM, base + LEFT);
      }
      if (col + 1 < n) {
        union(base + RIGHT, base + 4 + LEFT);
      }
      if (row + 1 < n) {
        union(base + BOTTOM, base + 4 * n + TOP);
      }
    }
  }
  return regions;
}

