function regionsBySlashes(grid) {
  // Draw each square as 3 x 3 pixels, mark the slash pixels, and count open areas with a flood fill.
  const n = grid.length, size = 3 * n;
  const wall = Array.from({ length: size }, () => new Array(size).fill(false));
  for (let r = 0; r < n; r++)
    for (let c = 0; c < n; c++)
      for (let d = 0; d < 3; d++) {
        if (grid[r][c] === '/') wall[3 * r + d][3 * c + 2 - d] = true;
        if (grid[r][c] === '\\') wall[3 * r + d][3 * c + d] = true;
      }
  let count = 0;
  for (let r = 0; r < size; r++)
    for (let c = 0; c < size; c++) {
      if (wall[r][c]) continue;
      count++;
      const stack = [[r, c]];
      wall[r][c] = true;
      while (stack.length) {
        const [y, x] = stack.pop();
        for (const [ny, nx] of [[y + 1, x], [y - 1, x], [y, x + 1], [y, x - 1]]) {
          if (ny < 0 || nx < 0 || ny >= size || nx >= size || wall[ny][nx]) continue;
          wall[ny][nx] = true;
          stack.push([ny, nx]);
        }
      }
    }
  return count;
}

