function generate(rand, size) {
  const n = size === 'large' ? 30 - Math.floor(rand() * 4) : 1 + Math.floor(rand() * 5);
  // Vary how often a square is blank so both open and densely cut boards appear.
  const blank = rand() * 0.6;
  const grid = [];
  for (let r = 0; r < n; r++) {
    let row = '';
    for (let c = 0; c < n; c++) {
      const roll = rand();
      row += roll < blank ? ' ' : rand() < 0.5 ? '/' : '\\';
    }
    grid.push(row);
  }
  return [grid];
}
